	-- first-person view
	["First-person view"] = { "Ego-Perspektive", "Primera persona", "Vue subjective" },
	["Camera in Lincoln's eyes: you see hands, weapon and the steering wheel. On by default, the choice is remembered"] = {
		"Kamera in Lincolns Augen: Hände, Waffe und Lenkrad im Blick. Standardmäßig an, die Wahl wird gespeichert",
		"Cámara en los ojos de Lincoln: ves manos, arma y volante. Activada por defecto, se recuerda la elección",
		"Caméra dans les yeux de Lincoln : mains, arme et volant visibles. Activée par défaut, le choix est mémorisé" },
	["Show body, hands and weapon"] = { "Körper, Hände und Waffe zeigen", "Mostrar cuerpo, manos y arma", "Afficher le corps, les mains et l'arme" },
	["Off hides the whole model, weapon included"] = { "Aus blendet das ganze Modell samt Waffe aus", "Desactivado oculta todo el modelo, arma incluida", "Désactivé masque tout le modèle, arme comprise" },
	["Also in vehicles"] = { "Auch in Fahrzeugen", "También en vehículos", "Aussi en véhicule" },
	["Driver's seat view; the camera follows the car"] = { "Blick vom Fahrersitz, die Kamera folgt dem Auto", "Vista desde el asiento del conductor; la cámara sigue al coche", "Vue du siège conducteur ; la caméra suit la voiture" },
	["Camera"] = { "Kamera", "Cámara", "Caméra" },
	["Camera mode"] = { "Kameramodus", "Modo de cámara", "Mode caméra" },
	["Game camera: native mouse, aim and driving — offset pulls view to the eyes. Locked: anchor rig"] = { "Spielkamera: native Maus, Zielen, Fahren — Offset zu den Augen. Fixiert: Anker", "Cámara del juego: ratón y mira nativos — offset a los ojos. Fija: ancla", "Caméra du jeu : souris et visée natives — offset vers les yeux. Fixée : ancre" },
	["Game camera: stand still, hold mouse still ~1 s to calibrate"] = { "Spielkamera: stillstehen, Maus ~1 s ruhig halten", "Cámara del juego: quieto, ratón inmóvil ~1 s", "Caméra du jeu : immobile, souris fixe ~1 s" },
	["Game camera: stop the car, hold mouse still ~1 s to calibrate"] = { "Im Auto: anhalten, Maus ~1 s ruhig", "En coche: para, ratón quieto ~1 s", "En voiture : arrêt, souris fixe ~1 s" },
	["Game camera"] = { "Spielkamera", "Cámara del juego", "Caméra du jeu" },
	["Locked camera"] = { "Fixierte Kamera", "Cámara fija", "Caméra fixée" },
	["Game camera: native mouse look and aiming. Locked camera: the fallback"] = { "Spielkamera: native Maussicht und Zielen. Fixierte Kamera: die Notlösung", "Cámara del juego: vista con ratón y apuntado nativos. Cámara fija: la alternativa", "Caméra du jeu : visée et vue à la souris natives. Caméra fixée : la solution de secours" },
	["Head bob"] = { "Kopfwippen", "Balanceo de la cabeza", "Balancement de la tête" },
	["How much the view follows the head while walking"] = { "Wie stark die Sicht beim Gehen dem Kopf folgt", "Cuánto sigue la vista a la cabeza al caminar", "À quel point la vue suit la tête en marchant" },
	["Off"] = { "Aus", "No", "Non" },
	["On"] = { "An", "Sí", "Oui" },
	["Low"] = { "Schwach", "Suave", "Léger" },
