	["Field of view"] = { "Sichtfeld", "Campo de visión", "Champ de vision" },
	["Game"] = { "Wie im Spiel", "Como en el juego", "Comme le jeu" },
	["Game keeps the game's own angle, aiming zoom included"] = { "„Wie im Spiel“ behält den eigenen Winkel samt Zielzoom", "«Como en el juego» mantiene el ángulo propio, zoom al apuntar incluido", "« Comme le jeu » garde l'angle d'origine, zoom de visée compris" },
	["Camera forward"] = { "Kamera nach vorn", "Cámara adelante", "Caméra en avant" },
	["Metres in front of the eyes; more if you see the inside of the head"] = { "Meter vor den Augen; mehr, wenn der Kopf von innen zu sehen ist", "Metros delante de los ojos; más si ves la cabeza por dentro", "Mètres devant les yeux ; plus si l'intérieur de la tête est visible" },
	["Camera height"] = { "Kamerahöhe", "Altura de la cámara", "Hauteur de la caméra" },
	["Metres above or below the eyes"] = { "Meter über oder unter den Augen", "Metros por encima o por debajo de los ojos", "Mètres au-dessus ou au-dessous des yeux" },
	["Speed correction"] = { "Tempoausgleich", "Corrección de velocidad", "Correction de vitesse" },
	["Switch it if at speed the view slides away from the head"] = { "Umschalten, wenn die Sicht bei Tempo vom Kopf wegrutscht", "Cámbialo si a velocidad la vista se aleja de la cabeza", "À changer si, en vitesse, la vue glisse loin de la tête" },
	["Service"] = { "Wartung", "Mantenimiento", "Maintenance" },
	["Recalibrate the camera"] = { "Kamera neu kalibrieren", "Recalibrar la cámara", "Recalibrer la caméra" },
	["Measure again if the view drifts off the eyes"] = { "Neu messen, wenn die Sicht von den Augen wegdriftet", "Medir de nuevo si la vista se aparta de los ojos", "Mesurer à nouveau si la vue s'écarte des yeux" },
	["Write camera state to the log"] = { "Kamerazustand ins Log schreiben", "Escribir el estado de la cámara en el registro", "Écrire l'état de la caméra dans le journal" },
	["ScriptHook.log: bones, camera, calibration"] = { "ScriptHook.log: Knochen, Kamera, Kalibrierung", "ScriptHook.log: huesos, cámara, calibración", "ScriptHook.log : os, caméra, calibrage" },
	["First-person: stand still and hold the mouse still for a second to set up the camera"] = { "Ego-Perspektive: eine Sekunde stillstehen und die Maus ruhig halten, die Kamera richtet sich ein", "Primera persona: quédate quieto y no muevas el ratón un segundo para ajustar la cámara", "Vue subjective : reste immobile et ne bouge pas la souris une seconde pour régler la caméra" },
	["First-person: stop the car and hold the mouse still for a second to set up the camera"] = { "Ego-Perspektive: das Auto kurz anhalten und die Maus ruhig halten, die Kamera richtet sich ein", "Primera persona: detén el coche un segundo y no muevas el ratón para ajustar la cámara", "Vue subjective : arrête la voiture une seconde et ne bouge pas la souris pour régler la caméra" },
	["First-person: ready"] = { "Ego-Perspektive: Kamera eingerichtet", "Primera persona: cámara ajustada", "Vue subjective : caméra réglée" },
	["First-person: the game camera did not follow, using the locked camera"] = { "Ego-Perspektive: die Spielkamera folgt nicht, fixierte Kamera aktiv", "Primera persona: la cámara del juego no responde, se usa la cámara fija", "Vue subjective : la caméra du jeu ne suit pas, caméra fixée activée" },
	["First-person: calibration cleared"] = { "Ego-Perspektive: Kalibrierung gelöscht, die Kamera wird neu gemessen", "Primera persona: calibración borrada, la cámara se medirá de nuevo", "Vue subjective : calibrage effacé, la caméra sera mesurée à nouveau" },
	["First-person: the game camera did not follow — try Recalibrate or the locked camera"] = { "Ego-Perspektive: die Spielkamera folgt nicht — neu kalibrieren oder die fixierte Kamera wählen", "Primera persona: la cámara del juego no responde — recalibra o usa la cámara fija", "Vue subjective : la caméra du jeu ne suit pas — recalibre ou passe en caméra fixée" },
	["Head camera"] = { "Kopfkamera", "Cámara en la cabeza", "Caméra dans la tête" },
	["Head camera: held at the eyes, like first-person mods in GTA. Game camera: the game's own camera, stops just behind the head on foot"] = { "Kopfkamera: an den Augen gehalten, wie Ego-Mods für GTA. Spielkamera: die eigene Kamera des Spiels, zu Fuß knapp hinter dem Kopf", "En la cabeza: fija en los ojos, como los mods en primera persona de GTA. Del juego: la cámara propia, a pie queda justo detrás de la cabeza", "Dans la tête : tenue aux yeux, comme les mods vue subjective de GTA. Du jeu : la caméra d'origine, à pied juste derrière la tête" },
	["Mouse sensitivity"] = { "Mausempfindlichkeit", "Sensibilidad del ratón", "Sensibilité de la souris" },
	["How fast the head camera turns with the mouse"] = { "Wie schnell sich die Kopfkamera mit der Maus dreht", "Lo rápido que gira la cámara en la cabeza con el ratón", "Vitesse de rotation de la caméra dans la tête à la souris" },
	["Frame lead"] = { "Bildvorlauf", "Adelanto de fotograma", "Avance d'image" },
	["Keeps the camera from trailing the head while running; turn off if it runs ahead"] = { "Damit die Kamera beim Laufen nicht hinter dem Kopf zurückbleibt; aus, wenn sie vorausläuft", "Evita que la cámara se quede atrás al correr; desactívalo si se adelanta", "Évite que la caméra traîne derrière la tête en courant ; désactive si elle prend de l'avance" },
	["Tests again how walking follows the view and how the game camera moves (stand still ~4 s)"] = { "Prüft neu, wie das Gehen der Sicht folgt und wie sich die Spielkamera bewegt (~4 s stillstehen)", "Vuelve a comprobar cómo el andar sigue a la vista y cómo se mueve la cámara del juego (quieto ~4 s)", "Reteste comment la marche suit le regard et comment bouge la caméra du jeu (immobile ~4 s)" },
	["First-person: stand still for a few seconds, setting up walking"] = { "Ego-Perspektive: ein paar Sekunden stillstehen, das Gehen wird eingerichtet", "Primera persona: quédate quieto unos segundos, ajustando el andar", "Vue subjective : reste immobile quelques secondes, réglage de la marche" },
	["First-person: walking does not follow the head camera here — use the game camera mode"] = { "Ego-Perspektive: das Gehen folgt der Kopfkamera nicht — Modus „Spielkamera“ wählen", "Primera persona: el andar no sigue a la cámara en la cabeza — usa la cámara del juego", "Vue subjective : la marche ne suit pas la caméra dans la tête — passe en caméra du jeu" },
	["First-person: shooting from a car uses the game's camera (it does not aim from the eyes here)"] = { "Ego-Perspektive: beim Schießen aus dem Auto gilt die Spielkamera (von den Augen aus zielt sie hier nicht)", "Primera persona: al disparar desde el coche se usa la cámara del juego (aquí no apunta desde los ojos)", "Vue subjective : en tirant depuis une voiture, c'est la caméra du jeu (elle ne vise pas depuis les yeux ici)" },
	["First-person: the game camera did not follow — try Recalibrate or the head camera"] = { "Ego-Perspektive: die Spielkamera folgt nicht — neu kalibrieren oder die Kopfkamera wählen", "Primera persona: la cámara del juego no responde — recalibra o usa la cámara en la cabeza", "Vue subjective : la caméra du jeu ne suit pas — recalibre ou passe à la caméra dans la tête" },
	["Body turns with the view"] = { "Körper dreht sich mit der Sicht", "El cuerpo gira con la vista", "Le corps suit le regard" },
	["Standing still, Lincoln turns to where you look, like in GTA"] = { "Im Stand dreht sich Lincoln dorthin, wohin du schaust, wie in GTA", "Quieto, Lincoln gira hacia donde miras, como en GTA", "À l'arrêt, Lincoln se tourne là où tu regardes, comme dans GTA" },
	["Game camera: native mouse, aim and driving, held at the eyes. Locked camera: the fallback"] = { "Spielkamera: native Maus, Zielen und Fahren, an den Augen gehalten. Fixierte Kamera: die Notlösung", "Cámara del juego: ratón, mira y conducción nativos, fija en los ojos. Cámara fija: la alternativa", "Caméra du jeu : souris, visée et conduite natives, tenue aux yeux. Caméra fixée : la solution de secours" },
	["Measures how the game camera moves (stand still ~2 s). Use it if the view drifts off the eyes"] = { "Misst, wie sich die Spielkamera bewegt (~2 s stillstehen). Nötig, wenn die Sicht von den Augen wegdriftet", "Mide cómo se mueve la cámara del juego (quieto ~2 s). Úsalo si la vista se aparta de los ojos", "Mesure comment bouge la caméra du jeu (immobile ~2 s). À utiliser si la vue s'écarte des yeux" },
	-- first person from the game's own camera config (tables.sds)
	["First-person: the game's own first-person camera is installed (tables.sds)"] = { "Ego-Perspektive: die eigene Ego-Kamera des Spiels ist installiert (tables.sds)", "Primera persona: está instalada la cámara en primera persona del propio juego (tables.sds)", "Vue subjective : la caméra subjective du jeu est installée (tables.sds)" },
	-- the names the release gives the camera patch (2026-10-21)
	["First-person: the camera patch is not installed — IRIDIUM\\fp_camera\\INSTALL_FP_CAMERA.bat with the game closed"] = { "Ego-Perspektive: der Kamera-Patch ist nicht installiert — IRIDIUM\\fp_camera\\INSTALL_FP_CAMERA.bat bei geschlossenem Spiel", "Primera persona: el parche de cámara no está instalado — IRIDIUM\\fp_camera\\INSTALL_FP_CAMERA.bat con el juego cerrado", "Vue subjective : le patch caméra n'est pas installé — IRIDIUM\\fp_camera\\INSTALL_FP_CAMERA.bat jeu fermé" },
	["First person stays: it is in the game camera config. Third person again: IRIDIUM\\fp_camera\\UNINSTALL_FP_CAMERA.bat"] = { "Die Ego-Perspektive bleibt: sie steckt in der Kamerakonfiguration. Wieder dritte Person: IRIDIUM\\fp_camera\\UNINSTALL_FP_CAMERA.bat", "La primera persona sigue: está en la configuración de cámara. Volver a tercera persona: IRIDIUM\\fp_camera\\UNINSTALL_FP_CAMERA.bat", "La vue subjective reste : elle est dans la configuration caméra. Retour à la troisième personne : IRIDIUM\\fp_camera\\UNINSTALL_FP_CAMERA.bat" },
	["Check the game camera config"] = { "Kamerakonfiguration des Spiels prüfen", "Comprobar la configuración de cámara del juego", "Vérifier la configuration caméra du jeu" },
	["First person inside the game's own camera (the camera patch, IRIDIUM\\fp_camera): native mouse, walking and aiming"] = { "Ego-Perspektive in der Kamera des Spiels selbst (der Kamera-Patch, IRIDIUM\\fp_camera): native Maus, Gehen und Zielen", "Primera persona en la propia cámara del juego (el parche de cámara, IRIDIUM\\fp_camera): ratón, andar y apuntado nativos", "Vue subjective dans la caméra même du jeu (le patch caméra, IRIDIUM\\fp_camera) : souris, marche et visée natives" },
	["First-person: turn the view on, then check"] = { "Ego-Perspektive: erst die Ansicht einschalten, dann prüfen", "Primera persona: activa la vista y luego comprueba", "Vue subjective : active d'abord la vue, puis vérifie" },
	["Without the game camera config, and in vehicles. Head camera: held at the eyes. Game camera: the game's own, stops just behind the head on foot"] = { "Ohne Kamerakonfiguration und in Fahrzeugen. Kopfkamera: an den Augen gehalten. Spielkamera: die eigene, zu Fuß knapp hinter dem Kopf", "Sin la configuración de cámara y en vehículos. En la cabeza: fija en los ojos. Del juego: la propia, a pie justo detrás de la cabeza", "Sans la configuration caméra, et en véhicule. Dans la tête : tenue aux yeux. Du jeu : celle d'origine, à pied juste derrière la tête" },
	["Only without the game camera config (with it vehicles always use the head camera). Head camera: held at the eyes. Game camera: the game's own, stops just behind the head on foot"] = { "Nur ohne Kamerakonfiguration des Spiels (mit ihr in Fahrzeugen immer die Kopfkamera). Kopfkamera: an den Augen gehalten. Spielkamera: die eigene, zu Fuß knapp hinter dem Kopf", "Solo sin la configuración de cámara del juego (con ella, en vehículos siempre la cámara en la cabeza). En la cabeza: fija en los ojos. Del juego: la propia, a pie justo detrás de la cabeza", "Seulement sans la configuration caméra du jeu (avec elle, en véhicule toujours la caméra dans la tête). Dans la tête : tenue aux yeux. Du jeu : celle d'origine, à pied juste derrière la tête" },
	["On foot without the game camera config: keeps the camera from trailing the head while running; never used in vehicles"] = { "Zu Fuß ohne Kamerakonfiguration: damit die Kamera beim Laufen nicht hinter dem Kopf zurückbleibt; in Fahrzeugen nie benutzt", "A pie sin la configuración de cámara: evita que la cámara se quede atrás al correr; nunca se usa en vehículos", "À pied sans la configuration caméra : évite que la caméra traîne derrière la tête en courant ; jamais utilisé en véhicule" },
	["Field of view in vehicles"] = { "Sichtfeld im Fahrzeug", "Campo de visión en vehículos", "Champ de vision en véhicule" },
	["Wider in a car for the sense of speed; on foot the angle stays the game's"] = { "Im Auto breiter für mehr Tempogefühl; zu Fuß bleibt der eigene Winkel des Spiels", "Más amplio en el coche para sentir la velocidad; a pie se mantiene el ángulo del juego", "Plus large en voiture pour la sensation de vitesse ; à pied l'angle du jeu reste" },
	["Game keeps the game's own angle, aiming zoom included; with the game camera config it is always the game's"] = { "„Wie im Spiel“ behält den eigenen Winkel samt Zielzoom; mit der Kamerakonfiguration immer der des Spiels", "«Como en el juego» mantiene el ángulo propio con el zoom al apuntar; con la configuración de cámara siempre es el del juego", "« Comme le jeu » garde l'angle d'origine, zoom de visée compris ; avec la configuration caméra c'est toujours celui du jeu" },
	-- where each first-person setting acts (2026-10-20)
	["How fast the head camera turns with the mouse: in vehicles, and on foot in the head camera mode without the game camera config. Elsewhere the game's own mouse setting applies"] = { "Wie schnell sich die Kopfkamera mit der Maus dreht: in Fahrzeugen und zu Fuß im Modus Kopfkamera ohne Kamerakonfiguration. Sonst gilt die Mauseinstellung des Spiels", "Lo rápido que gira la cámara en la cabeza con el ratón: en vehículos y a pie en el modo cámara en la cabeza sin la configuración de cámara. En lo demás rige el ajuste de ratón del propio juego", "Vitesse de rotation de la caméra dans la tête à la souris : en véhicule, et à pied en mode caméra dans la tête sans la configuration caméra. Ailleurs, le réglage de souris du jeu s'applique" },
	["Off keeps the view steady. On foot: the eyes' up and down while walking (not with a gun in hand, in cover or a fight). In a vehicle: the driver's head"] = { "Aus hält die Sicht ruhig. Zu Fuß: das Auf und Ab der Augen beim Gehen (nicht mit Waffe in der Hand, in Deckung oder im Kampf). Im Fahrzeug: der Kopf des Fahrers", "Desactivado mantiene la vista estable. A pie: el sube y baja de los ojos al caminar (no con un arma en la mano, a cubierto ni en una pelea). En un vehículo: la cabeza del conductor", "Désactivé garde la vue stable. À pied : la montée et la descente des yeux en marchant (pas avec une arme en main, à couvert ni en combat). En véhicule : la tête du conducteur" },
	["On foot. With the game camera config also with a gun from the hip; in the sights the zoom is the game's"] = { "Zu Fuß. Mit der Kamerakonfiguration auch mit Waffe aus der Hüfte; im Visier ist der Zoom der des Spiels", "A pie. Con la configuración de cámara también con arma desde la cadera; al apuntar el zoom es el del juego", "À pied. Avec la configuration caméra aussi avec une arme à la hanche ; en visée, le zoom est celui du jeu" },
	["Wider in a car for the sense of speed; on foot the field of view above applies"] = { "Im Auto breiter für mehr Tempogefühl; zu Fuß gilt das Sichtfeld darüber", "Más amplio en el coche para sentir la velocidad; a pie rige el campo de visión de arriba", "Plus large en voiture pour la sensation de vitesse ; à pied, le champ de vision ci-dessus s'applique" },
	["Head camera on foot (without the game camera config, which places the camera itself): metres in front of the eyes; more if you see the inside of the head"] = { "Kopfkamera zu Fuß (ohne Kamerakonfiguration, die die Kamera selbst setzt): Meter vor den Augen; mehr, wenn der Kopf von innen zu sehen ist", "Cámara en la cabeza a pie (sin la configuración de cámara, que coloca la cámara por sí misma): metros delante de los ojos; más si ves la cabeza por dentro", "Caméra dans la tête à pied (sans la configuration caméra, qui place elle-même la caméra) : mètres devant les yeux ; plus si l'intérieur de la tête est visible" },
	["Camera forward in vehicles"] = { "Kamera nach vorn im Fahrzeug", "Cámara adelante en vehículos", "Caméra en avant en véhicule" },
	["Metres in front of the driver's eyes, minus behind them; more if you see the inside of the head"] = { "Meter vor den Augen des Fahrers, minus dahinter; mehr, wenn der Kopf von innen zu sehen ist", "Metros delante de los ojos del conductor, menos detrás; más si ves la cabeza por dentro", "Mètres devant les yeux du conducteur, moins derrière ; plus si l'intérieur de la tête est visible" },
	["Metres above or below the eyes, on foot and in vehicles"] = { "Meter über oder unter den Augen, zu Fuß und im Fahrzeug", "Metros por encima o por debajo de los ojos, a pie y en vehículos", "Mètres au-dessus ou au-dessous des yeux, à pied et en véhicule" },
	-- stairs and the camera with a gun (2026-10-21)
	["Smooth steps"] = { "Stufen glätten", "Suavizar escalones", "Lisser les marches" },
	["With the game camera config: on stairs the camera rises and sinks smoothly instead of jumping with the feet (at most 12 cm behind)"] = { "Mit der Kamerakonfiguration: auf Treppen steigt und sinkt die Kamera sanft, statt mit den Füßen zu springen (höchstens 12 cm hinterher)", "Con la configuración de cámara: en escaleras la cámara sube y baja con suavidad en vez de saltar con los pies (como mucho 12 cm de retraso)", "Avec la configuration caméra : dans les escaliers, la caméra monte et descend en douceur au lieu de sauter avec les pieds (12 cm de retard au plus)" },
	["Camera with a gun: right"] = { "Kamera mit Waffe: rechts", "Cámara con arma: derecha", "Caméra avec arme : droite" },
	["Camera with a gun: down"] = { "Kamera mit Waffe: unten", "Cámara con arma: abajo", "Caméra avec arme : bas" },
	["With the game camera config and a gun in hand, not aiming down the sights: metres to the right toward the weapon, so it is in view. Needs the current ASI (right mouse button = aiming)"] = { "Mit der Kamerakonfiguration, Waffe in der Hand, ohne Zielen: Meter nach rechts zur Waffe, damit sie zu sehen ist. Braucht das aktuelle ASI (rechte Maustaste = Zielen)", "Con la configuración de cámara y un arma en la mano, sin apuntar: metros a la derecha hacia el arma para verla. Necesita el ASI actual (botón derecho = apuntar)", "Avec la configuration caméra et une arme en main, sans viser : mètres vers la droite, vers l'arme, pour la voir. Demande l'ASI à jour (clic droit = visée)" },
	["Camera in the sights: right"] = { "Kamera im Visier: rechts", "Cámara al apuntar: derecha", "Caméra en visée : droite" },
	["Camera in the sights: down"] = { "Kamera im Visier: unten", "Cámara al apuntar: abajo", "Caméra en visée : bas" },
	["With the game camera config, aiming down the sights (right mouse button): metres to the right, on top of the config's place for each weapon; minus is to the left. Needs the current ASI"] = { "Mit der Kamerakonfiguration, beim Zielen (rechte Maustaste): Meter nach rechts, zusätzlich zum Platz aus der Konfiguration je Waffe; Minus ist links. Braucht das aktuelle ASI", "Con la configuración de cámara, al apuntar (botón derecho): metros a la derecha, sobre el sitio de la configuración para cada arma; menos es a la izquierda. Necesita el ASI actual", "Avec la configuration caméra, en visée (clic droit) : mètres vers la droite, en plus de la place de la configuration pour chaque arme ; moins, c'est à gauche. Demande l'ASI à jour" },
	["Aiming down the sights: metres down; minus is up"] = { "Beim Zielen: Meter nach unten; Minus ist oben", "Al apuntar: metros hacia abajo; menos es hacia arriba", "En visée : mètres vers le bas ; moins, c'est vers le haut" },
	["With a gun in hand, not aiming down the sights: metres down toward the weapon"] = { "Waffe in der Hand, ohne Zielen: Meter nach unten zur Waffe", "Con un arma en la mano, sin apuntar: metros hacia abajo, hacia el arma", "Arme en main, sans viser : mètres vers le bas, vers l'arme" },
	-- the head ahead of the camera (crouch 2026-10-21, any move 2026-10-22) and the view on by default
	["Hide the body when the head is ahead of the camera"] = { "Körper ausblenden, wenn der Kopf vor der Kamera ist", "Ocultar el cuerpo cuando la cabeza está delante de la cámara",
		"Masquer le corps quand la tête passe devant la caméra" },
	["With the game camera config: starting off sharply, crouching and getting up, Lincoln's head leans ahead of the camera, which cannot move forward, and his eyes and mouth would show from inside. On: the body is hidden for that moment. Off: it stays"] = {
		"Mit der Kamerakonfiguration: beim abrupten Losgehen, in der Hocke und beim Aufstehen neigt sich Lincolns Kopf vor die Kamera, die nicht nach vorn kann, und Augen und Mund wären von innen zu sehen. An: der Körper wird für diesen Moment ausgeblendet. Aus: er bleibt",
		"Con la configuración de cámara: al arrancar de golpe, al agacharse y al levantarse, la cabeza de Lincoln se adelanta a la cámara, que no puede adelantarse, y se verían los ojos y la boca por dentro. Sí: el cuerpo se oculta ese momento. No: se queda",
		"Avec la configuration caméra : en démarrant brusquement, en s'accroupissant et en se relevant, la tête de Lincoln passe devant la caméra, qui ne peut pas avancer, et on verrait les yeux et la bouche de l'intérieur. Oui : le corps est masqué pendant ce moment. Non : il reste" },
	["First-person view is on (F4 - Camera turns it off)"] = { "Ego-Perspektive ist an (aus: F4 — Kamera)", "Primera persona activada (desactivar: F4 — Cámara)", "Vue subjective activée (désactiver : F4 — Caméra)" },
	-- takedowns in first person (2026-10-21)
	["Takedowns in first person"] = { "Takedowns aus der Ego-Perspektive", "Derribos en primera persona", "Éliminations en vue subjective" },
	["Quiet ones"] = { "Leise", "Sigilosos", "Discrètes" },
	["Quiet and stunned"] = { "Leise und betäubte", "Sigilosos y aturdidos", "Discrètes et étourdis" },
	["All but the brutal (experimental)"] = { "Alle außer den brutalen (experimentell)", "Todos menos los brutales (experimental)", "Toutes sauf les brutales (expérimental)" },
	["With the game camera config: the camera stays at the eyes in a takedown from behind, of a seated man, of one on the phone or at a mounted gun. With stunned: also finishing a stunned one (a civilian after a beating too). All but the brutal (experimental): also from cover, over cover, on the run and of a man on the floor. The brutal ones keep the game's camera. Needs the current ASI"] = {
		"Mit der Kamerakonfiguration: die Kamera bleibt an den Augen bei einem Takedown von hinten, eines Sitzenden, eines am Telefon oder am Geschütz. Mit betäubten: auch das Erledigen eines Betäubten (auch eines Zivilisten nach einer Prügelei). Alle außer den brutalen (experimentell): auch aus der Deckung, über die Deckung, im Lauf und eines Mannes am Boden. Die brutalen behalten die Kamera des Spiels. Braucht das aktuelle ASI",
		"Con la configuración de cámara: la cámara se queda en los ojos en un derribo por la espalda, de alguien sentado, al teléfono o en una ametralladora. Con aturdidos: también rematar a un aturdido (también a un civil tras una pelea). Todos menos los brutales (experimental): también desde cobertura, sobre la cobertura, a la carrera y de alguien en el suelo. Los brutales siguen con la cámara del juego. Necesita el ASI actual",
		"Avec la configuration caméra : la caméra reste aux yeux lors d'une élimination par derrière, d'un homme assis, au téléphone ou à une mitrailleuse. Avec étourdis : aussi achever un étourdi (un civil après une bagarre aussi). Toutes sauf les brutales (expérimental) : aussi depuis un abri, par-dessus un abri, en courant et d'un homme au sol. Les brutales gardent la caméra du jeu. Demande l'ASI à jour" },
	-- third person on the fly, keys, vehicle camera, effects, cover, presets (2026-10-22)
	["View on foot"] = { "Ansicht zu Fuß", "Vista a pie", "Vue à pied" },
	["First person"] = { "Ego-Perspektive", "Primera persona", "Vue subjective" },
	["Third person"] = { "Third-Person", "Tercera persona", "Troisième personne" },
	["Third person: with the camera patch the camera moves back behind Lincoln's shoulder on the fly (mouse, walking and aiming stay the game's). Without the patch it is the game's own camera on foot and first person in vehicles only, the patch is not needed for that. The view key switches it"] = {
		"Third-Person: mit dem Kamera-Patch fährt die Kamera im Spiel hinter Lincolns Schulter zurück (Maus, Gehen und Zielen bleiben die des Spiels). Ohne den Patch zu Fuß die eigene Kamera des Spiels und die Ego-Perspektive nur im Fahrzeug, dafür braucht es den Patch nicht. Die Ansichtstaste schaltet um",
		"Tercera persona: con el parche de cámara, la cámara se aleja al instante detrás del hombro de Lincoln (ratón, caminar y apuntar siguen siendo los del juego). Sin el parche, a pie la cámara propia del juego y la primera persona solo en vehículos, para eso no hace falta el parche. La tecla de vista lo cambia",
		"Troisième personne : avec le patch caméra, la caméra recule à la volée derrière l'épaule de Lincoln (souris, marche et visée restent celles du jeu). Sans le patch, à pied la caméra du jeu et la vue subjective seulement en véhicule, le patch n'est pas nécessaire pour cela. La touche de vue bascule" },
	-- first person in vehicles only, the driver's lean, the hat, the sights per kind of gun (2026-10-22)
	["First-person view is on in vehicles; on foot the game's camera (F4 - Camera)"] = {
		"Ego-Perspektive im Fahrzeug an; zu Fuß die Kamera des Spiels (F4 — Kamera)",
		"Primera persona activada en vehículos; a pie la cámara del juego (F4 — Cámara)",
		"Vue subjective activée en véhicule ; à pied la caméra du jeu (F4 — Caméra)" },
	["Camera follows the driver's lean"] = { "Kamera folgt dem Vorbeugen des Fahrers",
		"La cámara sigue la inclinación del conductor", "La caméra suit le penché du conducteur" },
	["The camera at the driver's eyes is fixed to the seat. Leaning forward (braking, a turn) his head came in front of it. On: along the car the camera follows his eyes forward once they are over 4 cm off the seat, without the small shakes"] = {
		"Die Kamera an den Augen des Fahrers ist am Sitz fest. Beim Vorbeugen (Bremsen, eine Kurve) kam sein Kopf vor sie. An: entlang des Autos folgt die Kamera seinen Augen nach vorn, sobald sie über 4 cm vom Sitz sind, ohne das kleine Wackeln",
		"La cámara en los ojos del conductor está fija al asiento. Al inclinarse hacia delante (frenada, curva) su cabeza quedaba delante. Sí: a lo largo del coche la cámara sigue sus ojos hacia delante en cuanto se alejan más de 4 cm del asiento, sin las pequeñas sacudidas",
		"La caméra aux yeux du conducteur est fixée au siège. En se penchant (freinage, virage), sa tête passait devant. Oui : le long de la voiture, la caméra suit ses yeux vers l'avant dès qu'ils s'écartent de plus de 4 cm du siège, sans les petites secousses" },
	["Hide the hat"] = { "Hut ausblenden", "Ocultar el sombrero", "Masquer le chapeau" },
	["In first person, on foot and at the wheel, Lincoln's hat is hidden: its brim came into the view. Shown again in third person, with the game's camera and when the view is off. Glasses cannot be hidden this way"] = {
		"In der Ego-Perspektive, zu Fuß und am Steuer, wird Lincolns Hut ausgeblendet: die Krempe kam ins Bild. Wieder da in der Third-Person, mit der Kamera des Spiels und wenn die Ansicht aus ist. Brillen lassen sich so nicht ausblenden",
		"En primera persona, a pie y al volante, el sombrero de Lincoln se oculta: el ala entraba en la vista. Vuelve en tercera persona, con la cámara del juego y con la vista apagada. Las gafas no se pueden ocultar así",
		"En vue subjective, à pied et au volant, le chapeau de Lincoln est masqué : son bord entrait dans le champ. Il revient en troisième personne, avec la caméra du jeu et quand la vue est éteinte. Les lunettes ne peuvent pas être masquées ainsi" },
	["Camera in the sights for"] = { "Kamera im Visier für", "Cámara al apuntar para", "Caméra en visée pour" },
	["Pistols and revolvers"] = { "Pistolen und Revolver", "Pistolas y revólveres", "Pistolets et revolvers" },
	["Submachine guns"] = { "Maschinenpistolen", "Subfusiles", "Pistolets-mitrailleurs" },
	["Shotguns"] = { "Schrotflinten", "Escopetas", "Fusils à pompe" },
	["Rifles"] = { "Gewehre", "Rifles", "Fusils" },
	["Sniper rifles"] = { "Scharfschützengewehre", "Rifles de francotirador", "Fusils de précision" },
	["Other guns"] = { "Andere Waffen", "Otras armas", "Autres armes" },
	["With the game camera config the place in the sights below is kept for each kind of gun; this row picks the kind the two rows show, at first the one in hand. Move it where the gun does not cover the target"] = {
		"Mit der Kamerakonfiguration wird der Platz im Visier (die zwei Zeilen darunter) je Waffenart gespeichert; diese Zeile wählt die Art, die sie zeigen, zuerst die Waffe in der Hand. So verschieben, dass die Waffe das Ziel nicht verdeckt",
		"Con la configuración de cámara, el lugar al apuntar (las dos filas de abajo) se guarda para cada tipo de arma; esta fila elige el tipo que muestran, primero el arma en la mano. Muévelo para que el arma no tape el objetivo",
		"Avec la configuration caméra, la place en visée (les deux lignes dessous) est gardée pour chaque type d'arme ; cette ligne choisit le type affiché, d'abord l'arme en main. Déplace-la pour que l'arme ne cache pas la cible" },
	["View key"] = { "Ansichtstaste", "Tecla de vista", "Touche de vue" },
	["Switches first and third person where you are: on foot the row above, in a vehicle «Also in vehicles»; turns the view on when it is off. Needs the current ASI"] = {
		"Schaltet zwischen Ego- und Third-Person, wo du gerade bist: zu Fuß die Zeile darüber, im Fahrzeug „Auch in Fahrzeugen“; schaltet die Ansicht ein, wenn sie aus ist. Braucht das aktuelle ASI",
		"Cambia entre primera y tercera persona donde estés: a pie la fila de arriba, en un vehículo «También en vehículos»; enciende la vista si está apagada. Necesita el ASI actual",
		"Bascule entre première et troisième personne là où tu es : à pied la ligne au-dessus, en véhicule « Aussi en véhicule » ; allume la vue si elle est éteinte. Demande l'ASI à jour" },
	["Look back in a vehicle"] = { "Im Fahrzeug zurückblicken", "Mirar atrás en el vehículo", "Regarder en arrière en véhicule" },
	["Mouse 3"] = { "Mausrad", "Rueda del ratón", "Molette" },
	["Hold the key to look back over your shoulder from the driver's seat. Needs the current ASI"] = {
		"Taste halten, um vom Fahrersitz über die Schulter zurückzublicken. Braucht das aktuelle ASI",
		"Mantén la tecla para mirar atrás por encima del hombro desde el asiento del conductor. Necesita el ASI actual",
		"Maintiens la touche pour regarder en arrière par-dessus l'épaule depuis le siège conducteur. Demande l'ASI à jour" },
	["Camera in vehicles"] = { "Kamera im Fahrzeug", "Cámara en el vehículo", "Caméra en véhicule" },
	["At the driver's eyes"] = { "An den Augen des Fahrers", "En los ojos del conductor", "Aux yeux du conducteur" },
	["On the hood"] = { "Auf der Motorhaube", "En el capó", "Sur le capot" },
	["At the driver's eyes, or on the hood (experimental: the hood is longer or shorter by car)"] = {
		"An den Augen des Fahrers oder auf der Motorhaube (experimentell: die Haube ist je nach Auto länger oder kürzer)",
		"En los ojos del conductor o en el capó (experimental: el capó es más largo o más corto según el coche)",
		"Aux yeux du conducteur ou sur le capot (expérimental : le capot est plus ou moins long selon la voiture)" },
	["Preset"] = { "Voreinstellung", "Preajuste", "Préréglage" },
	["Choose"] = { "Auswählen", "Elegir", "Choisir" },
	["Standard"] = { "Standard", "Estándar", "Standard" },
	["Steady"] = { "Ruhig", "Estable", "Stable" },
	["Immersive"] = { "Immersiv", "Inmersivo", "Immersif" },
	["Several rows at once. Standard: low head bob, light effects. Steady: no head bob, no effects. Immersive: full head bob, strong effects"] = {
		"Mehrere Zeilen auf einmal. Standard: schwaches Kopfwippen, leichte Effekte. Ruhig: kein Wippen, keine Effekte. Immersiv: volles Wippen, starke Effekte",
		"Varias filas a la vez. Estándar: balanceo suave, efectos ligeros. Estable: sin balanceo ni efectos. Inmersivo: balanceo completo, efectos fuertes",
		"Plusieurs lignes à la fois. Standard : balancement léger, effets légers. Stable : sans balancement ni effets. Immersif : balancement complet, effets forts" },
	["Camera effects"] = { "Kameraeffekte", "Efectos de cámara", "Effets de caméra" },
	["Light"] = { "Leicht", "Ligeros", "Légers" },
	["Strong"] = { "Stark", "Fuertes", "Forts" },
	["With the game camera config, in first person: a kick of the camera on each shot (stronger for shotguns, rifles and revolvers), a slow sway in the sights, a dip on landing after a fall"] = {
		"Mit der Kamerakonfiguration, in der Ego-Perspektive: ein Ruck der Kamera bei jedem Schuss (stärker bei Schrotflinten, Gewehren und Revolvern), langsames Schwanken im Visier, ein Absacken bei der Landung nach einem Sturz",
		"Con la configuración de cámara, en primera persona: un golpe de cámara en cada disparo (más fuerte con escopetas, rifles y revólveres), un balanceo lento al apuntar, un hundimiento al aterrizar tras una caída",
		"Avec la configuration caméra, en vue subjective : un à-coup de la caméra à chaque tir (plus fort pour les fusils à pompe, fusils et revolvers), un léger balancement en visée, un affaissement à l'atterrissage après une chute" },
	["Camera follows the head in cover"] = { "Kamera folgt dem Kopf in Deckung", "La cámara sigue la cabeza en cobertura", "La caméra suit la tête à couvert" },
	["With the game camera config: peeking out of cover and ducking, the camera goes with the head sideways and in height"] = {
		"Mit der Kamerakonfiguration: beim Hervorschauen aus der Deckung und Ducken folgt die Kamera dem Kopf seitlich und in der Höhe",
		"Con la configuración de cámara: al asomarse de la cobertura y agacharse, la cámara sigue la cabeza de lado y en altura",
		"Avec la configuration caméra : en se penchant hors de l'abri et en se baissant, la caméra suit la tête sur le côté et en hauteur" },
	["First-person: third person on foot does not work here (the camera does not move back); first person stays"] = {
		"Ego-Perspektive: Third-Person zu Fuß geht hier nicht (die Kamera fährt nicht zurück), es bleibt die Ego-Perspektive",
		"Primera persona: la tercera persona a pie no funciona aquí (la cámara no se aleja); se queda la primera",
		"Vue subjective : la troisième personne à pied ne fonctionne pas ici (la caméra ne recule pas) ; la vue subjective reste" },
	["First-person view: first person in vehicles"] = { "Ansicht: Ego-Perspektive im Fahrzeug", "Vista: primera persona en el vehículo", "Vue : subjective en véhicule" },
	["First-person view: the game's camera in vehicles"] = { "Ansicht: Kamera des Spiels im Fahrzeug", "Vista: cámara del juego en el vehículo", "Vue : caméra du jeu en véhicule" },
	["First-person view: third person on foot"] = { "Ansicht zu Fuß: Third-Person", "Vista a pie: tercera persona", "Vue à pied : troisième personne" },
	["First-person view: first person on foot"] = { "Ansicht zu Fuß: Ego-Perspektive", "Vista a pie: primera persona", "Vue à pied : subjective" },
	["First-person: preset applied"] = { "Ego-Perspektive: Voreinstellung übernommen", "Primera persona: preajuste aplicado", "Vue subjective : préréglage appliqué" },
	-- the field of view in the sights (2026-10-21)
	["On foot. With the game camera config also with a gun from the hip; in the sights the next row applies"] = { "Zu Fuß. Mit der Kamerakonfiguration auch mit Waffe aus der Hüfte; im Visier gilt die Zeile darunter", "A pie. Con la configuración de cámara también con arma desde la cadera; al apuntar rige la fila de abajo", "À pied. Avec la configuration caméra aussi avec une arme à la hanche ; en visée, la ligne suivante s'applique" },
	["Field of view in the sights"] = { "Sichtfeld im Visier", "Campo de visión al apuntar", "Champ de vision en visée" },
	["On foot"] = { "Wie zu Fuß", "Como a pie", "Comme à pied" },
	["With the game camera config, aiming down the sights (right mouse button). Game: the config's zoom for each weapon; On foot: no zoom, the angle above"] = { "Mit der Kamerakonfiguration, beim Zielen (rechte Maustaste). „Wie im Spiel“: der Zoom der Konfiguration je Waffe; „Wie zu Fuß“: kein Zoom, das Sichtfeld darüber", "Con la configuración de cámara, al apuntar (botón derecho). «Como en el juego»: el zoom de la configuración para cada arma; «Como a pie»: sin zoom, el ángulo de arriba", "Avec la configuration caméra, en visée (clic droit). « Comme le jeu » : le zoom de la configuration pour chaque arme ; « Comme à pied » : pas de zoom, l'angle ci-dessus" },
	["Only without the game camera config: switch it if at speed the camera trails the head or runs ahead. The head camera in a vehicle never uses it"] = { "Nur ohne Kamerakonfiguration: umschalten, wenn die Kamera bei Tempo hinter dem Kopf zurückbleibt oder vorausläuft. Die Kopfkamera im Fahrzeug nutzt es nie", "Solo sin la configuración de cámara: cámbialo si a velocidad la cámara se queda atrás o se adelanta. La cámara en la cabeza en un vehículo nunca lo usa", "Seulement sans la configuration caméra : à changer si, en vitesse, la caméra traîne derrière la tête ou prend de l'avance. La caméra dans la tête en véhicule ne l'utilise jamais" },

